	class IntList {
		class Info {
			int idx;
			int val;

			public Info(int idx, int val) {
				this.idx = idx;
				this.val = val;
			}

			public String toString() {
				return "(" + idx + ", " + val + ")";
			}
		}

		class InfoComparator implements Comparator<Info> {
			boolean bAsc;

			public InfoComparator(boolean bAsc) {
				this.bAsc = bAsc;
			}

			public int compare(Info o1, Info o2) {
				int sign = bAsc ? 1 : -1;
				if (o1.val < o2.val)
					return -1 * sign;
				else if (o1.val > o2.val)
					return 1 * sign;
				return 0;
			}
		}

		List<Info> list = new ArrayList<>();
		InfoComparator asc = new InfoComparator(true);
		InfoComparator desc = new InfoComparator(false);

		public void add(int val) {
			list.add(new Info(list.size(), val));
		}

		public void add(int idx, int val) {
			list.add(new Info(idx, val));
		}

		public int getIdx(int idx) {
			return list.get(idx).idx;
		}

		public int getVal(int idx) {
			return list.get(idx).val;
		}

		public int getLastVal() {
			return list.get(list.size() - 1).val;
		}

		public void remove(int idx) {
			list.remove(idx);
		}

		public void removeLast() {
			list.remove(list.size() - 1);
		}

		public int size() {
			return list.size();
		}

		public void sort(boolean bAsc) {
			if (bAsc)
				Collections.sort(list, asc);
			else
				Collections.sort(list, desc);
		}
	}

	class Point {
		int x;
		int y;

		public Point(int x, int y) {
			this.x = x;
			this.y = y;
		}

		public Point(Point pt) {
			this.x = pt.x;
			this.y = pt.y;
		}

		public boolean equals(Object o) {
			if (o instanceof Point) {
				Point that = (Point) o;
				return (x == that.x) && (y == that.y);
			}
			return false;
		}

		public int hashCode() {
			return x + (y * 31);
		}

		public String toString() {
			return "(" + x + ", " + y + ")";
		}
	}

	class PointComparator implements Comparator<Point> {
		int mode;

		public PointComparator(int prop, boolean bAsc) {
			switch (prop) {
			case 1:
				if (bAsc)
					this.mode = 11;
				else
					this.mode = 12;
				break;
			case 2:
				if (bAsc)
					this.mode = 21;
				else
					this.mode = 22;
				break;
			default:
				throw new RuntimeException();
			}
		}

		public int compare(Point p1, Point p2) {
			switch (mode) {
			case 11:
				return 1 * Integer.compare(p1.x, p2.x);
			case 12:
				return -1 * Integer.compare(p1.x, p2.x);
			case 21:
				return 1 * Integer.compare(p1.y, p2.y);
			case 22:
				return -1 * Integer.compare(p1.y, p2.y);
			}
			throw new IllegalStateException();
		}
	}

