        f[0] = 1;
        f[1] = 1;
        for(int i = 2; i <= n; i++){
            f[i] = (f[i-2] + f[i-1]) % MOD;
        }

        long count = 1;
        int length;
        if(m == 0){
            count = f[n];
        }else{
            length = a[0];
            if(length != 0){
                count = (count * f[length -1]) % MOD;
            }
