                length = a[i+1] - a[i] -1;
                if(length == 0){
                    System.out.println(0);
                    return;
                }
                count = (count * f[length -1]) % MOD;
            }
            length = n - a[m-1];
            if(length != 0){
                count = (count * f[length -1]) % MOD;
            }
        }

        System.out.println(count);
