		int A = a.charAt(1);

		int B = s[k].charAt(1);

		int index = sort.indexOf(k);


		while(A==B && j<a.length()) {


			A += a.charAt(j);

			B += s[k].charAt(j);

			j++;
		}

		if(A>B){

			sort.add(index+1,i);

		}

		if(A<B) {

			sort.add(index,i);
		}



