        ArrayList<Long> mods = new ArrayList<>();

        for(long i=L; i<=N; i++){
            mods.add(i % 2019L);
        }

        Collections.sort(mods);

        long ans = Long.MAX_VALUE;

        N = mods.size();

        for(int i=0; i<N-1; i++){
