import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int input = sc.nextInt();
		int nums[] = { 8, 27, 64, 125, 216, 343, 512, 729, 32, 243, 128, 512 };
		for (int i = 1; i <= 32; i++) {
			if (input == i * i) {
				System.out.println(i * i);
				break;
			}
			if ((input > i * i) && input < (i + 1) * (i + 1)) {
				int binary = i * i;
				for (int s : nums) {
					if (s <= input && s > binary) {
						System.out.println(s);
						break;
					}
					System.out.println(binary);
					break;
				}
			}
		}
	}
}

import java.util.Scanner;

public class Main {
    public static double temp(int t, int x) {
        return t - x * 0.006;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int t = sc.nextInt();
        int a = sc.nextInt();
        int[] h = new int[n];
        for (int i = 0; i < n; i ++) {
            h[i] = sc.nextInt();
        }

        double minDiff = Math.abs(a - temp(t, h[0]));
        int num = 0;
        for (int i = 1; i < n; i++) {
            double hoge = Math.abs(a - temp(t, h[i]));
            if (minDiff > hoge) {
                minDiff = hoge;
                num = i;
            }
        }

        System.out.println(num + 1);
    }
}

