import java.util.Scanner;

class Main{
  static void swap(int[] a, int idx1, int idx2){
    int t = a[idx1]; a[idx1] = a[idx2]; a[idx2] = t;
  }

  static void quickSort(int[] a, int left, int right){
    int pl = left;
    int pr = right;
    int x  = a[(pl+pr)/2];

    do{
      while (a[pl] < x) pl++;
      while (a[pr] > x) pr--;
      if(pl <= pr)
         swap(a, pl++, pr--);
    }while(pl <= pr);

   if(left < pr) quickSort(a,left,pr);
   if(pl < right) quickSort(a,pl,right);
 }

  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int K = sc.nextInt();
    int[] p = new int[N];
    for(int i =0; i<N;i++){
      p[i] = sc.nextInt();
    }

    quickSort(p,0,N-1);

    int sum = 0;
    for(int i = 0; i<K; i++){
      sum += p[i];
    }
    System.out.println(sum);
  }
}

import java.util.LinkedList;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in); 

		LinkedList<Process> processQueue = new LinkedList<Process>();

		int n = sc.nextInt();
		int quantum = sc.nextInt();
		for (int i = 0; i < n; i++) {
			processQueue.add(new Process(sc.next(), sc.nextInt()));
		}

		for (int spendTime = 0; !processQueue.isEmpty(); ) {
			Process run = processQueue.remove();
			if (run.pRemain > quantum) {
				run.pRemain -= quantum;
				processQueue.add(run);
				spendTime += quantum;
			} else if (run.pRemain == quantum) {
				run.pRemain -= quantum;
				spendTime += quantum;
				printProcess(run, spendTime);
			} else {
				spendTime += run.pRemain;
				run.pRemain = 0;
				printProcess(run, spendTime);
			}
		}

        sc.close();
	}

	private static void printProcess(Process run, int eTime) {
		StringBuffer str = new StringBuffer();

		str.append(run.pName);
		str.append(" ");
		str.append(eTime);

		System.out.println(str);
	}
}

