        if(val2==0){
            return val1;
        }else{
            return gcd(val2, val1%val2);
        }
    }

    public static int gcd(int... val){
        int len = val.length;
        int g = gcd(val[0], val[1]);
        for(int i=1; i<len-1; i++){
            g = gcd(g, val[i+1]);
        }
        return g;
    }
}

