  public void run() {

    int N = sc.nextInt();
    int M = sc.nextInt();

    memo = new long[N+1];

    hole = new boolean[N+1];
    for (int i=0; i<M; i++) {
      hole[sc.nextInt()] = true;
    }

    Arrays.fill(memo, -1);

    System.out.println(solve(N));
  }


  public long solve(int n) {
    if (hole[n]) {
      return 0;
    }

    if (memo[n] >= 0) {
      return memo[n];
    }

    if (n <= 1) {
      return 1;
    }

    //System.out.println(n);

    return memo[n] = (solve(n-1) + solve(n-2)) % MOD;
  }

  public static class Mathf {

    public static int max(int[] a) {
      int M = a[0];
      for (int i = 1; i < a.length; i++) {
        M = Math.max(M, a[i]);
      }
