import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner s = new Scanner(System.in);
		int A = s.nextInt();
		int B = s.nextInt();
		int ans = max(A, B);
		System.out.println(ans);
	}

	public static int max(int A, int B) {
		int ans = A;

		if (B > ans) {
			ans = B;
			B = B - 1;
		} else {
			A = A - 1;
		}

		if (A >= B) {
			ans += A;
		} else {
			ans += B;
		}
		return ans;
	}
}

