            for (int j = i + 1; j < x.length; j++) {
                int sum = 0;
                for (int k = 0; k < x[i].length; k++) {
                    sum += (x[i][k] - x[j][k]) * (x[i][k] - x[j][k]);
                }
                boolean isInteger = false;
