class Solver {
    public void solve(long N, long[] d) {
        long ans = 0;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                ans += d[i] * d[j];
            }
        }
        System.out.println(ans);
    }
}

