		while (curSTART<N) {
			if (curSTART+5<=N) {
				String test = S.substring(curSTART,curSTART+5);
				if (test.equals("dream")) {
					curSTART+=5;
					if (curSTART+2<=N) {
						if (S.substring(curSTART,curSTART+2).equals("er")) {
							curSTART+=2;
						}
					}
					if (curSTART+1<=N) {
						if (S.substring(curSTART,curSTART+1).equals("a")) {
							curSTART-=2;
							//Reset due to erase word being after dream 
							//(not dreamer)
						}
					}
