        for (int i = 0; i < n - 1; i++) {
            if (h[i + 1] < h[i]) {
                h[i]--;
                if (i != 0 && (h[i - 1] > h[i] || h[i + 1] < h[i])) {
                    ans = false;
                    break;
                }
            }
        }
        System.out.println(ans?"Yes":"No");
    }
}

