  public static int gcd(int a,int b){
    if(a<b){
      int aa=a;a=b;b=aa;
    }
    while(a%b!=0){
      int c=a%b;
      a=b;b=c;
    }
    return b;
  }

  public static void pr(String str){
    System.out.print(str);
  }
  public static void pl(String str){
    System.out.println(str);
  }
}

