public class Solution {

    public static void main(String[] args) throws Exception {

        new Solution().go();
    }

    PrintWriter out;
    Reader in;
    BufferedReader br;

    Solution() throws IOException {

        try {

            //br = new BufferedReader( new FileReader("input.txt") );
            //in = new Reader("input.txt");
            in = new Reader("input.txt");
