        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = 3;
            int[][] c = new int[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    c[i][j] = in.nextInt();
                }
