				if (data[head] == 0) {
					count++;
					System.out.println(str[head] + " " + quantum);
				} 
			}

			if (count == top) break;

			head++;
			if (head == top) head = 0;
		}
	}

	int Quantum(int x, int q) {

		if ( x < q) {
			quantum += x;
			return 0;
		} else {
			x -= q;
			quantum += q;
		}

		return x;

	}
}

