public class Main{
    public static void main(String[] args){
        Deque<String> formula = new ArrayDeque<String>();
        Scanner scan = new Scanner(System.in);
        while(scan.hasNext()){
            String input = scan.next();
            switch(input){
                case "+":
                    formula.push(String.valueOf(Double.parseDouble(formula.poll())+Double.parseDouble(formula.poll())));
                    break;
                case "-":
                    formula.push(String.valueOf(-1*Double.parseDouble(formula.poll())+Double.parseDouble(formula.poll())));                    
                    break;
                case "/":
                    formula.push(String.valueOf(1.0/Double.parseDouble(formula.poll())*Double.parseDouble(formula.poll())));
                    break;
                case "*":
                    formula.push(String.valueOf(Double.parseDouble(formula.poll())*Double.parseDouble(formula.poll())));
                    break;
                default:
                    formula.push(input);
                    break;
            }
        }
        if((Double ans=Double.parseDouble(formula.poll())==(int)ans){
            System.out.println((int)ans);
        }else{
            System.out.println(ans);
        }
    }
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int[] A = new int[N];
		for (int i = 0; i < N; i++) {
			A[i] = sc.nextInt();
		}
		output(A, N);
		insertionSort(A, N);
		sc.close();
	}

	public static void insertionSort(int[] A, int N) {
		for (int i = 1; i < N; i++) {
			int v = A[i];
			int j = i - 1;
			while (j >= 0 && A[j] > v) {
				A[j + 1] = A[j];
				j--;
			}
			A[j + 1] = v;
			output(A, N);
		}
	}

	public static void output(int[] A, int N) {
		for (int i = 0; i < N; i++) {
			if (i > 0) {
				System.out.print(" ");
			}
			System.out.print(A[i]);
		}
		System.out.printf("\n");
	}
}

