        stac = first;
        for(int i=0;i<n-1;i++){
            next = sc.nextInt();
            if((next - first)>max){
                max = next - first;                
            }
            first = next;
        }
        if((k + stac - next)>max){
            max = k + stac - next;
        }
        sc.close();
        System.out.println(max);
    }
}

