      } else if (2 <= i && i <= S.length() - 2 && c == 'C') {
        countC++;
      } else {
        if (!('a' <= c && c <= 'z')) {
          System.out.println("WA");
          return;
        }
      }
    }
    if (countC != 1) {
      System.out.println("WA");
      return;
    }

    System.out.println("AC");
  }
}

