        int n = sc.nextInt();
        int k = sc.nextInt();
        List<Integer> list = new ArrayList<>();
        for(int i=0; i<n; i++) {
            list.add(sc.nextInt());
        }
        if(n <= k) {
            System.out.println(0);
            return;
        }
        Collections.sort(list);
