import java.io.PrintWriter;
import java.util.Scanner;
import java.util.HashMap;
import java.util.Collections;
import java.util.ArrayList;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DigitsMultiplication solver = new DigitsMultiplication();
        solver.solve(1, in, out);
        out.close();
    }

    static class DigitsMultiplication {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            long n = in.nextLong();
            HashMap<Long, Long> map = primeFactorize(n);
            ArrayList<Long> list = new ArrayList<>(map.keySet());
            list.sort(Collections.reverseOrder());
            long a = 1;
            long b = 1;

            for (int i = 0; i < list.size(); i++) {
                Long key = list.get(i);
                Long limit = map.get(key);
                for (int j = 0; j < limit; j++) {
                    if (a < b) {
                        a *= key;
                    } else {
                        b *= key;
                    }
                }
            }

            int target = Math.max(digits(a), digits(b));
            out.println(target);
        }

        public int digits(long x) {
            int ans = 0;
            while (x > 0) {
                x /= 10;
                ans++;
            }
            return ans;
        }

        static HashMap<Long, Long> primeFactorize(long x) {
            HashMap<Long, Long> result = new HashMap<>();
            for (long i = 2; i * i <= x; i++) {
                if (x % i != 0) {
                    continue;
                }
                long ex = 0;
                while (x % i == 0) {
                    ex++;
                    x /= i;
                }
                result.put(i, ex);
            }
            if (x != 1) {
                result.put(x, 1L);
            }
            return result;
        }

    }
}

