    static long step2(int x){
        if(memo[x] > -1) return memo[x];
        int b = 0;
        for(int i = 0; i < m; i++){
            if(a[i] < x - 2) break;
            else if(x - 1 == a[i]) b += 1;
            else if(x - 2 == a[i]) b += 2;
        }
        if(x >= 2){
            if(b == 3){
                return 0;
            }else if(b == 1){
                memo[x] = step2(x - 2);
                return memo[x];
            }else if(b == 2){
                memo[x] = step2(x - 1);
                return memo[x];
            }
            else{
                memo[x] = step2(x - 1) + step2(x - 2);
                return memo[x];
            }
        }else return 1;
    }

