		for (int i = n.length - 1; 0 < i; i--) {
			if (n[i - 1] > n[i]) {
				n[i - 1] = n[i - 1] - 1;
			}
		}
		for (int i = 0; i < n.length - 1; i++) {
			if (n[i + 1] < n[i]) {
				str = "No";
			}
		}
		System.out.println(str);
	}
}

