        public void solve(InputReader in, PrintWriter out) {
        	int s = in.nextInt();

        	HashSet<Integer> set = new HashSet<Integer>();

        	int next = s;
        	int i=1;
        	do {
        		set.add(next);
        		if(next%2==1)
        			next = next*3+1;
        		else
        			next = next/2;
        		i++;
        	}
        	while(!set.contains(next));
        	out.println(i);
        }
    }

