	    int[] s = new int[n];
	    int count = 0;
	    for (int i = 0; i < n; i++) {
		s[i] = Integer.parseInt(input[i]);
		count += s[i];
	    }
	    double m = count / n;
	    double sigma = 0;
	    for (int i = 0; i < n; i++) {
		sigma += (s[i] - m) * (s[i] - m);
	    }
	    double a = Math.sqrt(sigma / n);
	    System.out.println(a);
	}	
    }
}

