            int ti = m.get(w)-100;
            if(ti>0) {
                q.add(w);
                m.replace(w,ti);
                time+=100;
            }
            else{
                time+=m.get(w);
                done.add(w+" "+String.valueOf(time));
                m.replace(w,0);
                T--;
            }
        }
        for(String s: done){
            System.out.println(s);
        }
    }
    public static void main(String[] args) throws Exception{
        run(args);
    }
}

