        for (int i = 0; i < N; i++) {
            for (int k = 0; k < M; k++) {
                for (int j = 0; j < L; j++) {
                    C[i][j] += A[i][k] * B[k][j];
                }
            }
        }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < L; j++) {
                if (j > 0) sysout.print(' ');
                sysout.print(C[i][j]);
            }
            sysout.println();
        }
    }

