	private static void  selectionSort(int a[],int n) {

		int count=0,temp=0,minj;

		for(int i=0;i<n;i++) {
			minj=i;
			for(int j=i;j<n;j++) 
				if(a[j]<a[minj]) 
					minj=j;
				if(minj!=i) {
					temp=a[i];
					a[i]=a[minj];
					a[minj]=temp;
					count++;
				}
		}

		for(int i=0;i<n-1;i++)
			System.out.print(a[i]+" ");
		System.out.println(a[n-1]);
		System.out.println(count);

	}

}

