	 * @param intNum1
	 * @param intNum2
	 */
	public static void SharpPaint(int intNum1, int intNum2) {

		//'＃'か'.' trueが'#'
		boolean booSharp = true;

		//たての分　ループ
		for(int i = 0; i < intNum1; i++) {

			//偶数の行は'#'から始める
			if(i % 2 == 0) {

				booSharp = true;

			} else {

				booSharp = false;

			}

			//よこの分　ループ
			for(int j = 0; j < intNum2; j++) {

				//'#'と'.'を交互に表示
				if(booSharp) {

					System.out.print("#");

					booSharp = false;

				} else {

					System.out.print(".");

					booSharp = true;

				}



			}
			//改行
			System.out.println("");
		}

		//改行
		System.out.println("");

	}
}

