    private void solve() {
        try {
            int N = sc.nextInt();
            int a[] = new int[N];
            for(int i=0; i<N; i++) {
                a[i] = sc.nextInt();
            }

            int alice = 0;
            int bob = 0;

            quickSort(a, 0, N-1);

            for(int i = N-1; i>=0; i-=2) {
                alice += a[i];
                if(i-1>=0) bob += a[i-1]; 
           }

            System.out.println(alice-bob);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void quickSort(int arr[], int begin, int end) {
        if (begin < end) {
            int partitionIndex = partition(arr, begin, end);

            quickSort(arr, begin, partitionIndex-1);
            quickSort(arr, partitionIndex+1, end);
        }
    }

    private int partition(int arr[], int begin, int end) {
        int pivot = arr[end];
        int i = (begin-1);

        for (int j = begin; j < end; j++) {
            if (arr[j]<= pivot) {
                i++;

                int swapTemp = arr[i];
                arr[i]= arr[j];
                arr[j]= swapTemp;
            }
        }

        int swapTemp = arr[i+1];
        arr[i+1]= arr[end];
        arr[end]= swapTemp;

        return i+1;
    }

    private class Scanner {
        String[] s;
        int i;
        BufferedReader br;
        String regex = " ";

        public Scanner() {
            s = new String[0];
