   public static void main(String[] args) {
      Scanner sc = new Scanner(System.in);

      int k = sc.nextInt();

      long sum = 0;

      for (int j = 1; j < k + 1; j++) {
         for (int i = 1; i < k + 1; i++) {
            for (int h = 1; h < k + 1; h++) {
               int s = gcd(j, i);
               int t = gcd(s, h);
               sum = sum + t;
            }
         }
      }
      System.out.println(sum);

   }

   private static int gcd(int m, int n) {
      if (m < n)
         return gcd(n, m);
      if (n == 0)
         return m;
      return gcd(n, m % n);
   }

}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        PrintWriter out = new PrintWriter(System.out);
        InputStreamScanner in = new InputStreamScanner(System.in);
        new Main().solve(in, out);
        out.flush();
    }

    private void solve(InputStreamScanner in, PrintWriter out) {
        int i = Integer.parseInt(in.next() + in.next());
        for (int j = 0; j < 1000; j++) {
            if (j*j > i) {
                out.println("No");
                return;
            }
            if (j*j == i) {
                out.println("Yes");
                return;
            }
        }
    }

    static class InputStreamScanner {

        private InputStream in;

        private byte[] buf = new byte[1024];
        private int len = 0;
        private int off = 0;

        InputStreamScanner(InputStream in)	{
            this.in = in;
        }

        String next() {
            StringBuilder sb = new StringBuilder();
            for (int b = skip(); !isSpace(b);){
                sb.appendCodePoint(b);
                b = read();
            }
            return sb.toString();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        char nextChar() {
            return (char)skip();
        }

        int skip() {
            for (int b; (b = read()) != -1;) {
                if (!isSpace(b)) {
                    return b;
                }
            }
            return -1;
        }

        private boolean isSpace(int c) {
            return c < 33 || c > 126;
        }

        private int read() {
            if (len == -1) {
                throw new InputMismatchException("End of Input");
            }
            if (off >= len){
                off = 0;
                try {
                    len = in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException(e.getMessage());
                }
                if (len <= 0) {
                    return -1;
                }
            }
            return buf[off++];
        }
    }
}

