                if (values[i] < values[i - 1]) {
                    if (!changed[i - 1]) {
                        values[i - 1] = values[i - 1] - 1;
                        changed[i - 1] = true;
                        hasChanged = true;
                    } else {
                        can = false;
                        break;
                    }
                }
            }
            if (hasChanged) {
                continue;
            }
            if (i >= values.length || !can) {
                break;
            }
        }
        if(can) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

