                sArray[i] = 1;
            }

            if(i % 2 == 0){
                zeroArray[i] = 0;
                oneArray[i] = 1;
            }else{
                zeroArray[i] = 1;
                oneArray[i] = 0;
            }
        }

        int oneDiff = 0;
        int zeroDIff = 0;

        for(int i=0; i<sArray.length; i++){
            if(sArray[i] != oneArray[i]){
                oneDiff++;
            }

            if(sArray[i] != zeroArray[i]){
                zeroDIff++;
            }
        }

        System.out.println(Math.min(oneDiff, zeroDIff));
    }
}

