	public void solve() throws IOException {
		FastScanner fs = new FastScanner();

		String s = fs.next();

		int index = 0;
		boolean yes = true;

		while(index < s.length()) {
			int retIndex;
			if(s.charAt(index) == 'e') {
				retIndex = checkStrOrStrer(s, index, erase);
				if(retIndex == -1) {
					yes = false;
					break;
				}
				index = retIndex;
			}else if(s.charAt(index) == 'd') {
				retIndex = checkStrOrStrer(s, index, dream);
