import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int q = sc.nextInt();
		String str = sc.next();

		int[][] quiz = new int[q][2];

		for (int i = 0; i < quiz.length; i++) {
			quiz[i][0] = sc.nextInt() - 1;
			quiz[i][1] = sc.nextInt();
		}

		char[] array = str.toCharArray();

		boolean ac = false;

		List<Integer> acBeginIndex = new ArrayList<>();
		List<Integer> acEndIndex = new ArrayList<>();

		int tmpIndex = 0;

		for (int j = 0; j < array.length; j++) {
			if (array[j] == 'A') {
				ac = true;
				tmpIndex = j;
			} else if (ac && array[j] == 'C') {
				acBeginIndex.add(tmpIndex);
				acEndIndex.add(j + 1);
				ac = false;
			} else {
				ac = false;
			}
		}

		StringBuilder sb = new StringBuilder();

		for (int i = 0; i < quiz.length; i++) {
			int count = 0;

			int tmp = 0;

			int first = -1;

			int limit = quiz[i][1] - quiz[i][0] + 3;

			while (first < 0 && quiz[i][1] > quiz[i][0] + tmp && quiz[i][0] + tmp < array.length && tmp < limit) {
				first = acBeginIndex.indexOf(quiz[i][0] + tmp++);
			}

			tmp = 0;

			int last = -1;

			while (last < 0 && quiz[i][0] < quiz[i][1] + tmp && quiz[i][1] + tmp >= 0 && tmp > limit * -1) {
				last = acBeginIndex.lastIndexOf(quiz[i][1] + tmp--);
			}

			if (last < 0 || first < 0 || last == first) {
				sb.append(0);
			} else {
				sb.append(last -  first + 1);
			}

			sb.append('\n');
		}

		System.out.print(sb.toString());
	}
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        Set<Integer> div1 = divisor(a);
        Set<Integer> div2 = divisor(b);

        int times = 1;
        for (Integer d1 : div1) {
            if (div2.contains(d1) && d1 != 1) {
                times = d1;
                break;
            }
        }

        System.out.println((long) (a * b / times));
    }

    static Set<Integer> divisor(int n) {
        Set<Integer> ret = new HashSet<>();
        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                ret.add(i);
                if (i != n / i)
                    ret.add(n / i);
            }
        }
        return ret;
    }
}

