          c = i;
        }
    }
    System.out.println(b + c -2);
  }

  static List<Long> factorization(long x) {
    List<Long> result = new ArrayList<>();

    while (x >= 4 && x % 2 == 0) {
        result.add((long)2);
        x /= 2;
    }
    long d = 3;
    long q = x / d;
    while (q >= d) {
        if (x % d == 0) {
            result.add(d);
            x = q;
        } else {
            d += 2;
        }
        q = x / d;
    }
    result.add(x);
    return result;
  }
}

