import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
	public static void main (String[] args) throws IOException
	{
		BufferedReader input = new BufferedReader (new InputStreamReader (System.in));

		int kaisuu = Integer.parseInt(input.readLine());

		int pointT = 0;

		int pointH = 0;

		//勝負をkaisuu回行う
		for(int kai = 0; kai < kaisuu; kai++)
		{
			String[] cards = input.readLine().split(" ");;

			for(int next = 0; next <= cards[0].length(); next++)
			{

				char head = 'a';

				int tarou = 0;

				int hanako = 0;

				int alphabet = 26;

				//太郎のカードの強さを調べる
				for(int num = 0; num < alphabet; num++,head++)
				{
					if(next == cards[0].length())
					{
						tarou = -1;

						break;
					}

					if(cards[0].charAt(next) == head)
					{
						tarou = num;

						break;
					}
				}

				head = 'a';

				//花子のカードの強さを調べる
				for(int num = 0; num < alphabet; num++,head++)
				{
					if(next == cards[1].length())
					{
						hanako = -1;

						break;
					}

					if(cards[1].charAt(next) == head)
					{
						hanako = num;

						break;
					}
				}

				//得点を振り分ける
				if(tarou > hanako)
				{
					pointT = pointT + 3;

					break;
				}

				else if(tarou < hanako)
				{
					pointH = pointH + 3;

					break;
				}

				else if(tarou == -1 && hanako == -1)
				{
					pointT++;

					pointH++;
				}
			}
		}

		System.out.println(pointT + " " + pointH);
	}
}

import java.util.Scanner;

public class Main
{

    public static int number;
    public static int[] A=new int[1000];

    public static void main(String[] args)
    {

        Scanner scan=new Scanner(System.in);
        number=scan.nextInt();

        for(int i=0;i<number;i++){
            A[i]=scan.nextInt();
            if(i!=number-1) System.out.print(A[i]+" ");
            if(i==number-1) System.out.print(A[i]);
        }
        System.out.println();

        insertionSort();

    }

    public static void insertionSort()
    {
        int v,j=0;
        for(int i=1;i<=number-1;i++)
        {
            v = A[i];
            j=i-1;
            while(j>=0 && A[j]>v)
            {
                A[j+1]=A[j];
                j--;
            }
            A[j+1]=v;

            for(int l=0;l<number;l++)
            {
                if (l != number - 1) System.out.print(A[l] + " ");
                if (l == number - 1) System.out.print(A[l]);
            }
            System.out.println();
        }

    }
}

