        int K = Integer.parseInt(inputs[0]);
        int S = Integer.parseInt(inputs[1]);

        int[] xPlusY = new int[2 * K + 1];
        for (int x = 0; x <= K; x++) {
            for (int y = 0; y <= K; y++) {
                xPlusY[x + y] += 1;
            }
        }

