      {
        A[i] = Integer.parseInt(s[i]);
      }
      int dist[] = new int[N];
      int max = 0;
      for(i = 0; i < N; i++)
      {
        dist[i] = Math.abs(A[(i + 1) % N] - A[i % N]);
        if(dist[i] > dist[max])
          max = i;
      }
      minDist = 0;
      for(i = 0; i < N; i++)
      {
        if(i != max)
          minDist = minDist + dist[i];
      }
      System.out.println(minDist);
    }
}

