	int cnt = 0;
        for (int i = 0; i < n; i++) {
	    int a = Integer.parseInt(scan.nextLine());
	    if (isPrime(a)) {
		System.out.println(a);
		cnt++;
	    }
	}
	System.out.println(cnt);
    }
    public static boolean isPrime(int a){
	if (a == 2) {
	    return true;
	}
	if (a % 2 == 0) {
	    return false;
	}
	for (int i = 3; i <= Math.sqrt(a); i++) {
	    if (a % i == 0) {
		return false;
	    }
	}
	return true;
    }
}

