		for(int i=0;i<m;i++){
			a.add(sc.nextInt());
		}
		step = new long[n+1];
		for(int i = 0; i <= n;i++){
			step[i] = 0;
		}
		step[0] = 1;
	}
	void solve(){
		for(int i = 1;i<=n;i++){
			if(a.contains(i)) continue;
			step[i] = step[i-1];
			if(i>1) step[i] += step[i-2];
			step[i]%=1000000007;
		}
		System.out.println(step[n]);
	}
}

