                // System.out.print(mat[i][j]+" ");
            }
            // System.out.println();
        }
        for(int i=1;i<n;i++){
            for(int j=0;j<m;j++){
                if(mat[i][j]==1){
                    mat[i][j]+=mat[i-1][j];
                }
                System.out.print(mat[i][j]+" ");
            }
